import{_ as a,a as t,b as r,c as s,d as n,e as l,f as d,g as p,h as c,i as m,j as u,k as h,l as f}from"./chunks/Install17a.WxJn2Ju7.js";import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as v}from"./chunks/EN.P9aPnFBv.js";import{_ as g}from"./chunks/Install17.CwCXrGHM.js";import{_ as z,o as b,c as _,a3 as y}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Installazione","description":"","frontmatter":{"source_hash":"4b874be737","source_commit":"0bbdbd2"},"headers":[],"relativePath":"it/install/install.md","filePath":"it/install/install.md"}'),A={name:"it/install/install.md"};function I(E,e,T,S,k,x){return b(),_("div",null,[...e[0]||(e[0]=[y('<p>Una volta scaricato, installa l&#39;apk di xDrip.</p><img src="'+a+'" style="zoom:50%;"><p>Nelle versioni recenti di Android vedrai un avviso di Google Play Protect che indica che l&#39;app non è sicura perché è stata creata per versioni precedenti di Android. Ignoralo con Altri dettagli e poi Installa comunque.</p><img src="'+t+'" style="zoom:50%;"><p><strong>Devi <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">autorizzare l&#39;installazione di app da origini sconosciute</a> nelle impostazioni di sicurezza di Android.</strong><br> Le versioni ufficiali di xDrip sono prive di virus e malware: essendo open source e controllate dallo sviluppatore principale, la loro distribuzione è sicura se le scarichi da GitHub.</p><img src="'+r+'" style="zoom:50%;"><p>Tocca <code>Impostazioni</code> e poi attiva <code>Consenti da questa fonte</code>.</p><img src="'+s+'" style="zoom:50%;"><p>Una volta installato, apri xDrip.</p><img src="'+n+'" style="zoom:75%;"><h3 id="understand-what-is-xdrip" tabindex="-1">Capire cos&#39;è xDrip <a class="header-anchor" href="#understand-what-is-xdrip" aria-label="Permalink to &quot;Capire cos&#39;è xDrip {#understand-what-is-xdrip}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title"><strong>Leggi</strong> l&#39;avviso importante</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+l+'" style="zoom:50%;"></p><img src="'+d+'" style="zoom:50%;"> Do NOT use or rely on this software or any associated materials for any medical purpose or decision. Do NOT rely on this system for any real-time alarms or time critical data. Do NOT use or rely on this system for treatment decisions or use as a substitute for professional healthcare judgement. All software and materials have been provided for informational purposes only as a proof of concept to assist possibilities for further research. No claims at all are made about fitness for any purpose and everything is provided **AS IS**. Any part of the system can fail at any time. Always seek the advice of a qualified healthcare professional for any medical questions. Always follow your glucose-sensor or other device manufacturers&#39; instructions when using any equipment; do not discontinue use of accompanying reader or receiver, other than as advised by your doctor. This software is not associated with or endorsed by any equipment manufacturer and all trademarks are those of their respective owners. Your use of this software is entirely at your own risk. No charge has been made by the developers for the use of this software. This is an open-source project which has been created by volunteers. The source code is published free and open-source for you to inspect and evaluate. By using this software and/or website you agree that you are over 18 years of age and have read, understood and agree to all of the above. </div><br><p><strong>Leggi</strong> l&#39;EULA.</p><div class="warning custom-block"><p class="custom-block-title">Assicurati di averla compresa del tutto prima di salvare.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+p+'" style="zoom:50%;"></p><p>xDrip MUST NOT BE USED TO MAKE MEDICAL DECISIONS.<br> IT IS A RESEARCH TOOL ONLY AND IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.<br> THE ENTIRE RISK AS TO THE QUALITY AND PERFORMANCE OF THE PROGRAM IS WITH YOU.<br> SHOULD THE PROGRAM PROVE DEFECTIVE, YOU ASSUME THE COST OF ALL NECESSARY SERVICING, REPAIR OR CORRECTION.</p></div><br><h3 id="authorize-background-activity" tabindex="-1">Autorizzare l&#39;attività in background <a class="header-anchor" href="#authorize-background-activity" aria-label="Permalink to &quot;Autorizzare l&#39;attività in background {#authorize-background-activity}&quot;">​</a></h3><p>xDrip deve avere il diritto di funzionare in background: deve essere escluso dall&#39;ottimizzazione della batteria. È essenziale per un corretto funzionamento. L&#39;app dovrebbe chiederti di concedere questa autorizzazione. Se non lo fa, o se devi verificarlo in seguito, controllalo in <code>Impostazioni</code> - <code>App</code> - <code>xDrip</code> del telefono. Consulta il manuale del telefono, perché dipende dalla versione di Android e dal produttore.</p><div class="admonition xdripitem"><p class="admonition-title">Consentire il permesso</p><p> xDrip+ ha bisogno di essere autorizzato in background per funzionare correttamente</p><p>      <span style="background-color:white;color:black;"> Ok </span></p></div><img src="'+c+'" style="zoom:75%;"><p><em>Nota: da Android 12 in poi non vedrai più la parola <strong>whitelisting</strong> (lista bianca).</em></p><p>Maggiori informazioni <a href="./../troubleshoot/savings.html#apps-battery-savings">qui</a>.</p><br><h3 id="authorize-notifications" tabindex="-1">Autorizzare le notifiche <a class="header-anchor" href="#authorize-notifications" aria-label="Permalink to &quot;Autorizzare le notifiche {#authorize-notifications}&quot;">​</a></h3><p>xDrip deve accedere alle notifiche del telefono per funzionare come previsto.</p><img src="'+m+'" style="zoom:75%;"><br><h2 id="verify-which-version-is-installed" tabindex="-1">Verificare quale versione è installata <a class="header-anchor" href="#verify-which-version-is-installed" aria-label="Permalink to &quot;Verificare quale versione è installata {#verify-which-version-is-installed}&quot;">​</a></h2><p>Tocca il tasto indietro del telefono finché non torni alla schermata principale. Seleziona il menu hamburger in alto a sinistra, poi <code>Stato del sistema</code>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p>  Stato del sistema</p></div><p>La versione attuale è indicata dopo <code>Versione</code>. Nell&#39;esempio qui sotto, 28 gennaio 2022.</p><img src="'+u+'" style="zoom:75%;"><p>Nelle versioni più recenti la trovi in tutte le pagine dello stato del sistema.</p><img src="'+h+'" style="zoom:76%;"><p>Vedi <a href="./../use/update.html">qui</a> per aggiornare o tornare a una versione precedente.</p><br><h2 id="make-sure-xdrip-will-not-be-put-to-sleep" tabindex="-1">Assicurarsi che xDrip non venga messo in sospensione <a class="header-anchor" href="#make-sure-xdrip-will-not-be-put-to-sleep" aria-label="Permalink to &quot;Assicurarsi che xDrip non venga messo in sospensione {#make-sure-xdrip-will-not-be-put-to-sleep}&quot;">​</a></h2><p>Queste sono le impostazioni predefinite, ma assicurati comunque che siano esattamente come mostrato qui sotto. Ogni volta che il telefono si aggiorna, torna a controllarle: disattiva e riattiva le caselle che devono essere attive per forzare le impostazioni.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni Meno Usate<br>   Altre opzioni<br>    Eseguire Collector in primo piano</p></div><p>Da quando il supporto di Android 7 è stato ritirato (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 luglio 2026</a>), il collector funziona sempre in primo piano su Android 8.0 e superiori: non c&#39;è più un interruttore per questa opzione. Il grafico della notifica persistente nella tendina del telefono è essenziale per mantenere attiva l&#39;app ed è sempre visualizzato.</p><div class="admonition xdripitem"><p class="admonition-title">Notifica Persistente Compatta <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Abilita per nascondere il grafico nelle notifiche e visualizzare solo il valore attuale di glucosio.</p></div><p>Se preferisci non mostrare il grafico nella notifica persistente, attiva <code>Notifica Persistente Compatta</code> per mostrare solo il valore attuale di glucosio.</p><div class="admonition xdripitem"><p class="admonition-title">Richiesta di Ottimizzazione della Batteria <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Con Android 6+ verifica che l&#39;ottimizzazione della batteria sia spenta. Raccomandato</p></div><p><code>Richiesta di Ottimizzazione della Batteria</code> deve essere <strong>disattivata</strong>, perché durante l&#39;installazione dovresti aver accettato l&#39;<a href="#authorize-background-activity">esclusione dall&#39;ottimizzazione della batteria</a>. In caso contrario, escludi xDrip dall&#39;ottimizzazione della batteria nelle impostazioni di Android.</p><div class="admonition xdripitem"><p class="admonition-title">Samsung Workaround <span class="symbol"><img src="'+v+'" style="zoom:75%;"></span></p><p> Usa workaround per evitare il comportamento non standard a Android degli telefonini Samsung. Senza questo, di solito non si riesce a ricevere dati.</p></div><p>In origine &quot;Samsung workaround&quot;, questa opzione corregge il mancato rispetto delle specifiche Android da parte di alcuni produttori. Con alcuni smartphone si attiva automaticamente. Consigliata.</p><h3 id="enable-location" tabindex="-1">Attivare la localizzazione <a class="header-anchor" href="#enable-location" aria-label="Permalink to &quot;Attivare la localizzazione {#enable-location}&quot;">​</a></h3><p>Nelle versioni più recenti di Android (dalla 6 in poi), la localizzazione è <a href="https://developer.android.com/training/location/permissions" target="_blank" rel="noreferrer">obbligatoria</a> per consentire la connessione Bluetooth Low Energy.<br> Se userai xDrip con un sensore o un bridge Bluetooth, <strong>devi</strong> attivare la localizzazione (Impostazioni Android -&gt; <a href="https://support.google.com/android/answer/3467281" target="_blank" rel="noreferrer">Posizione</a>) e autorizzare xDrip ad accedervi. Consulta il manuale del telefono, perché dipende dalla versione di Android e dal produttore.</p><p>Assicurati di selezionare Consenti sempre nelle impostazioni.</p><img src="'+f+'" style="zoom:75%;"><img src="'+g+'" style="zoom:75%;"><br><p>Passa alla <a href="./datasource.html">selezione della sorgente dati</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Ultima modifica 18/7/2026</em></a></p>',57)])])}const P=z(A,[["render",I]]);export{C as __pageData,P as default};
